                default:   dsel = D_SIGM;
            endcase
        end
        wire        ring_on = (cls == SFU_EXP) || (cls == SFU_RECIP) || (cls == SFU_RSQRT) || (cls == SFU_SIGM);
        reg  [6:0]  wp, rp;
        always @(posedge clk or negedge rst_n)
            if (!rst_n) begin wp <= 7'd0; rp <= 7'd0; end
`ifdef OT_TLS_MUT   // bench mutant: the ring read one word late (must FAIL)
            else begin wp <= wp + 7'd1; rp <= wp + 7'd2 - dsel[6:0]; end
`else
            else begin wp <= wp + 7'd1; rp <= wp + 7'd3 - dsel[6:0]; end      // rp(c+1) = wp(c+1) - (D - 2)
`endif
        wire [255:0] rq;
        reg  [LT-1:0] cq;                                                     // capture flops at the macro outputs
        always @(posedge clk) cq <= rq[LT-1:0];
        ot_sram_1r1w_128x256_m1_r2c2 u_tlm (.clk(clk), .r_ce_in(ring_on), .r_addr_in(rp), .rd_out(rq),
            .w_ce_in(ring_on), .w_addr_in(wp), .wd_in({{(256-LT){1'b0}}, t0}), .w_mask_in({256{1'b1}}),
            .rr_en(2'b00), .rr_addr(14'd0), .cr_en(2'b00), .cr_sel(16'd0));
        always @(*) tap = ring_on ? cq : t0;
`ifndef SYNTHESIS
        initial if (LT > 256 || D_SIGM > 129 || D_RECIP < 3 || D_RSQRT < 3 || D_EXP < 3)
            $fatal(1, "ot_hdc_vstream_lane TLS: line %0d b, class depths %0d/%0d/%0d/%0d outside the 128 x 256 ring",
                   LT, D_EXP, D_RECIP, D_RSQRT, D_SIGM);
`endif
    end endgenerate
    always @(*) begin
        case (cls)
            SFU_EXP:   begin tapv = tlv[TAP0 + D_EXP];   s_val = y_exp; end
            SFU_RECIP: begin tapv = tlv[TAP0 + D_RECIP]; s_val = y_rcp; end
            SFU_RSQRT: begin tapv = tlv[TAP0 + D_RSQRT]; s_val = y_rsq; end
            SFU_SIGM:  begin tapv = tlv[TAP0 + D_SIGM];  s_val = y_rcp; end
            default:   begin tapv = tlv[TAP0];           s_val = r14;   end
        endcase
    end

    // -- MC select (+1) -> multiplier (+LM) -> MD select (+1) -> multiplier (+LM) -> write
    reg [31:0] mc_x, mc_y, mc_b;
    reg        mc_v;
    reg [TT-1:0] mc_tail;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) mc_v <= 1'b0;
        else mc_v <= tapv;
    end
    always @(posedge clk) begin
        mc_x <= s_val; mc_b <= tap[LT-1 -: 32]; mc_y <= tap[LT-33 -: 32]; mc_tail <= tap[TT-1:0];
    end
    wire [31:0] mc_out, byp5, b5;
    wire fmc;
    ot_hdc_qmul #(.L(LM)) u_mc (clk, rst_n, mc_v && mc_tail[TT-1], mc_x, mc_y, mc_out, fmc);
    wire [TT-1:0] c_tail;
    wire [LM:0] vmc;
    ot_hdc_vline #(.D(LM)) u_vmc (.clk(clk), .rst_n(rst_n), .v(mc_v), .vd(vmc));
    ot_hdc_delay #(.W(64 + TT), .D(LM)) u_dmc (.clk(clk), .rst_n(rst_n), .d({mc_x, mc_b, mc_tail}),
                                             .q({byp5, b5, c_tail}));
    reg [31:0] md_x, md_y;
    reg        md_v;
    reg [TT-1:0] md_tail;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) md_v <= 1'b0;
        else md_v <= vmc[LM];
    end
    always @(posedge clk) begin
        md_x <= c_tail[TT-1] ? mc_out : byp5; md_y <= b5; md_tail <= c_tail;
    end
    wire [31:0] md_out, dbyp5;
    wire fmd;
    ot_hdc_qmul #(.L(LM)) u_md (clk, rst_n, md_v && md_tail[TT-2], md_x, md_y, md_out, fmd);
    wire [TT-1:0] o_tail;
    wire [LM:0] vmd;
    ot_hdc_vline #(.D(LM)) u_vmd (.clk(clk), .rst_n(rst_n), .v(md_v), .vd(vmd));
    ot_hdc_delay #(.W(32 + TT), .D(LM)) u_dmd (.clk(clk), .rst_n(rst_n), .d({md_x, md_tail}), .q({dbyp5, o_tail}));
    wire          o_mc, o_md;
    wire [1:0]    o_dst, o_red;
    wire          o_redsq;
    wire [AW-1:0] o_daddr, o_raddr;
    wire          o_ifirst, o_first8, o_final, o_last;
    wire [2:0]    o_p;
    assign {o_mc, o_md, o_dst, o_daddr, o_red, o_redsq, o_raddr, o_ifirst, o_first8, o_final, o_last, o_p} = o_tail;
    wire [31:0] out = o_md ? md_out : dbyp5;
    wire        ov = vmd[LM];
    assign retire = ov;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin vm_we <= 1'b0; kv_we <= 1'b0; end
        else begin
            vm_we <= ov && o_dst == 2'd1;
            kv_we <= ov && o_dst == 2'd2;
        end
    end
    always @(posedge clk) begin
        vm_waddr <= o_daddr; vm_wdata <= out;
        //: the KV cache holds BF16 (RNE), so attention products are exact BF16 x BF16
        kv_waddr <= o_daddr;
        kv_wdata <= KV_FP8 ? fp8r(out) : (out + 32'h7FFF + {31'd0, out[16]}) & 32'hFFFF0000;
    end


    assign l_ov = ov;
    assign l_out = out;
    assign l_red = o_red;
    assign l_redsq = o_redsq;
    assign l_raddr = o_raddr;
    assign l_last = o_last;
    reg lf;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) lf <= 1'b0;
        else lf <= fa | fb_ | fad | f_exp | f_e1 | f_rcp | f_rsq | fmc | fmd;
    end
    assign l_fault = lf;
endmodule
